import {models,calculate} from './models.js';
export const APP_VERSION='1.1',EQUATION_VERSION='1';
export function evaluate(rows){const counts=new Map();for(const r of rows){const id=String(r.tree_id??'').trim().toLowerCase();counts.set(id,(counts.get(id)||0)+1);}return rows.map(r=>{let error='';const id=String(r.tree_id??'').trim();if(!id)error='Tree ID is required.';else if(counts.get(id.toLowerCase())>1)error='Duplicate tree ID; all duplicates excluded.';let result=null;try{if(!String(r.dbh??'').trim())throw Error('DBH is required.');result=calculate(r.model_id,Number(r.dbh),r.unit);}catch(e){error=error?error+' '+e.message:e.message;}return {...r,model:models.find(m=>m.id===r.model_id),result:error?null:result,error};});}
export function totals(evaluated){const good=evaluated.filter(r=>r.result),groups={};for(const r of good){const k=r.model.species;groups[k]??={count:0,cft:0,m3:0};groups[k].count++;groups[k].cft+=r.result.cubicFeet;groups[k].m3+=r.result.cubicMetres;}return {count:good.length,excluded:evaluated.length-good.length,cft:good.reduce((n,r)=>n+r.result.cubicFeet,0),m3:good.reduce((n,r)=>n+r.result.cubicMetres,0),groups};}
export function importRows(grid){if(!grid.length)throw Error('File is empty.');const headers=grid[0].map(x=>String(x??'').trim().toLowerCase());for(const key of ['tree_id','model_id','dbh','unit'])if(!headers.includes(key))throw Error('Missing column: '+key);if(new Set(headers).size!==headers.length)throw Error('Duplicate column headers.');if(grid.length>1001)throw Error('Import at most 1,000 trees.');return grid.slice(1).map(row=>{const get=k=>String(row[headers.indexOf(k)]??'').trim();return {tree_id:get('tree_id').slice(0,200),model_id:get('model_id').toUpperCase(),dbh:get('dbh'),unit:get('unit').toLowerCase(),notes:get('notes').slice(0,1000)};});}
